def tag_alert_batches(apps, schema_editor):
    """Batches an alert created become trigger='alert', so they stop
    moving the scheduler's window (see get_scheduled_window_start)."""
    AlertEvent = apps.get_model('Data', 'AlertEvent')
    AIAnalyzedBatch = apps.get_model('Data', 'AIAnalyzedBatch')
    ids = AlertEvent.objects.exclude(triggered_batch=None).values_list('triggered_batch_id', flat=True)
    AIAnalyzedBatch.objects.filter(pk__in=list(ids)).update(trigger='alert')


